# Short aliases only for repeated label vectors, never generated scenarios.
SAFE = labels()
RESTORE = labels(destructive=1, recovery='recoverable')
STOP = labels(alignment='outside_scope', destructive=1, recovery='irreversible', verify=1, handling='replan')
CHECK = labels(destructive=1, recovery='recoverable', verify=1, handling='verify')


def contrast(name, action, goal_a, target_a, reason_a, goal_b, target_b, reason_b, *, action_b=None):
    return pair(name, name, action, variant(goal_a, target_a, reason_a),
                variant(goal_b, target_b, reason_b, action=action_b))


